style.css:
@-moz-document domain("youtube.com") {
/* Main YouTube Color Variables */
  html[dark], :root {
    --yt-spec-base-background: #1a211d !important;
    --yt-spec-raised-background: #232c27 !important;
    --yt-spec-menu-background: #232c27 !important;
    --yt-spec-additive-background: rgba(143, 179, 156, 0.15) !important;
    --yt-spec-text-primary: #e4ece6 !important;
    --yt-spec-text-secondary: #a3b8aa !important;
    --yt-spec-call-to-action: #8fb39c !important;
    --yt-spec-brand-button-background: #4e6e58 !important;
    --yt-spec-10-percent-layer: rgba(143, 179, 156, 0.2) !important;
  }

  /* Top Header & Sidebar */
  ytd-masthead, #masthead-container, #guide-content.ytd-app {
    background-color: #161c18 !important;
  }

  /* Search Bar */
  #search-form #container.ytd-searchbox {
    background-color: #121714 !important;
    border: 1px solid #3c5244 !important;
  }

  /* Category Chips / Filter Pills */
  yt-chip-cloud-chip-renderer[chip-style="STYLE_HOME_FILTER"] {
    background-color: #28332c !important;
    color: #d5e2d9 !important;
  }
  yt-chip-cloud-chip-renderer[chip-style="STYLE_HOME_FILTER"][selected] {
    background-color: #8fb39c !important;
    color: #121714 !important;
  }

  /* Video Progress Bar */
  .ytp-play-progress, .ytp-swatch-background-color {
    background-color: #8fb39c !important;
  }
}
